class Solution {
    private int lowerBound(int[] values,int target){
        int left=0,right=values.length;
        while(left<right){
            int middle=(left+right)>>>1;
            if(values[middle]<target)left=middle+1;
            else right=middle;
        }
        return left;
    }
    private void update(int[] bit,int index,int value){
        while(index<bit.length){
            bit[index]=Math.max(bit[index],value);
            index+=index&-index;
        }
    }
    private int query(int[] bit,int index){
        int answer=0;
        while(index>0){
            answer=Math.max(answer,bit[index]);
            index-=index&-index;
        }
        return answer;
    }
    public int[] maximumSumQueries(int[] nums1,int[] nums2,int[][] queries){
        int n=nums1.length,q=queries.length;
        Integer[] points=new Integer[n],order=new Integer[q];
        for(int i=0;i<n;i++)points[i]=i;
        for(int i=0;i<q;i++)order[i]=i;
        Arrays.sort(points,(a,b)->Integer.compare(nums1[b],nums1[a]));
        Arrays.sort(order,(a,b)->Integer.compare(queries[b][0],queries[a][0]));
        int[] values=nums2.clone();
        Arrays.sort(values);
        int[] bit=new int[n+1],answer=new int[q];
        int added=0;
        for(int queryIndex:order){
            int x=queries[queryIndex][0],y=queries[queryIndex][1];
            while(added<n&&nums1[points[added]]>=x){
                int point=points[added++];
                int rank=n-lowerBound(values,nums2[point]);
                update(bit,rank,nums1[point]+nums2[point]);
            }
            int best=query(bit,n-lowerBound(values,y));
            answer[queryIndex]=best==0?-1:best;
        }
        return answer;
    }
}

